3	import java.util.Comparator;
4	import java.util.Map;
5	
6	/**
7	 * Shared telephone canonicalization for the create-owner pipeline: reduces a telephone to
8	 * its E.164 form so validation, uniqueness checks and storage all compare the same value.
9	 */
10	final class OwnerTelephones {
11	
12	    /**
13	     * Country calling code (E.164 digits after the {@code '+'}) mapped to the exact number
14	     * of national digits a valid number for that country carries. Codes not listed here
15	     * carry no per-country length rule.
16	     */
17	    private static final Map<String, Integer> NATIONAL_DIGITS = Map.of("1", 10, "61", 9);
18	
19	    private OwnerTelephones() {
20	    }
21	
22	    /**
23	     * Canonicalizes {@code telephone} to E.164 (a leading {@code '+'} followed by 8 to 15
24	     * digits), or returns {@code null} when it cannot form a valid E.164 number.
25	     *
26	     * <p>Spaces, dashes and brackets are stripped. A leading {@code '+'} keeps the given
27	     * country code; otherwise country code {@code +61} is assumed and a single leading
28	     * {@code '0'} is dropped from the national digits. So {@code "0412 345 678"} becomes
29	     * {@code "+61412345678"} and {@code "+64 21 123 456"} becomes {@code "+6421123456"}.
30	     */
31	    static String toE164(String telephone) {
32	        if (telephone == null) {
33	            return null;
34	        }
35	        String cleaned = telephone.replaceAll("[\\s()\\-]", "");
36	        String digits;
37	        if (cleaned.startsWith("+")) {
38	            digits = cleaned.substring(1);
39	        }
40	        else {
41	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
42	            digits = "61" + national;
43	        }
44	        if (!digits.matches("\\d{8,15}")) {
45	            return null;
46	        }
47	        return "+" + digits;
48	    }
49	
50	    /**
51	     * Whether the E.164 {@code telephone}'s national-number length is correct for its
52	     * country calling code (e.g. {@code +61} requires 9 national digits, {@code +1}
53	     * requires 10). A country code with no known length rule is accepted.
54	     *
55	     * @param telephone an E.164 number (as produced by {@link #toE164(String)}).
56	     */
57	    static boolean hasValidNationalLength(String telephone) {
58	        if (telephone == null || !telephone.startsWith("+")) {
59	            return false;
60	        }
61	        String digits = telephone.substring(1);
62	        // Longest code first so "+61" is not matched as "+6"/"+1".
63	        String code = NATIONAL_DIGITS.keySet().stream()
64	                .filter(digits::startsWith)
65	                .max(Comparator.comparingInt(String::length))
66	                .orElse(null);
67	        if (code == null) {
68	            return true; // no per-country length rule
69	        }
70	        return digits.length() - code.length() == NATIONAL_DIGITS.get(code);
71	    }
72	}
